cd /app; python3 - <<'EOF'
p='Content.Server/Doors/Systems/FirelockSystem.cs'
t=open(p).read()
def r(o,n):
    global t
    assert t.count(o)==1,o
    t=t.replace(o,n)
r("""                    var p = gas.Pressure;
                    minPressure = Math.Min(minPressure, p);
                    maxPressure = Math.Max(maxPressure, p);
                    minTemperature = Math.Min(minTemperature, gas.Temperature);
                    maxTemperature = Math.Max(maxTemperature, gas.Temperature);
                }""","""                    var p = gas.Pressure;
                    minPressure = Math.Min(minPressure, p);
                    maxPressure = Math.Max(maxPressure, p);

                    // A vacuum has no meaningful temperature; it is a pressure hazard, not a fire hazard.
                    if (gas.TotalMoles > 0)
                    {
                        minTemperature = Math.Min(minTemperature, gas.Temperature);
                        maxTemperature = Math.Max(maxTemperature, gas.Temperature);
                    }
                }""")
r("""                minPressure = Math.Min(minPressure, p);
                maxPressure = Math.Max(maxPressure, p);
                minTemperature = Math.Min(minTemperature, local.Temperature);
                maxTemperature = Math.Max(maxTemperature, local.Temperature);
            }
            else
            {
                minPressure = Math.Min(minPressure, 0);
                maxPressure = Math.Max(maxPressure, 0);
                minTemperature = Math.Min(minTemperature, 0);
                maxTemperature = Math.Max(maxTemperature, 0);
            }""","""                minPressure = Math.Min(minPressure, p);
                maxPressure = Math.Max(maxPressure, p);
                if (local.TotalMoles > 0)
                {
                    minTemperature = Math.Min(minTemperature, local.Temperature);
                    maxTemperature = Math.Max(maxTemperature, local.Temperature);
                }
            }
            else
            {
                // No air on this tile at all: treat it as vacuum (pressure only).
                minPressure = Math.Min(minPressure, 0);
                maxPressure = Math.Max(maxPressure, 0);
            }""")
open(p,'w').write(t)
EOF
grep -n "TotalMoles" Content.Shared/Atmos/GasMixture.cs | head -3

